from math import log2, floor

def plus_grande_puissance_de_2(n):
    assert n > 0, 'n doit être positif'
    return floor(log2(n))

print(plus_grande_puissance_de_2(1))   # 0


def dec_vers_bin(n):
    if n == 0:
        return '0'

    res = ['0'] * (plus_grande_puissance_de_2(n) + 1)

    while n > 0:
        i = plus_grande_puissance_de_2(n)
        res[-1 - i] = '1'
        n -= 2 ** i

    return ''.join(res)

