def dec_vers_bin(n):
    if n == 0:
        return "0"
    poids = 1
    while poids * 2 <= n:        # le plus grand poids qui ne depasse pas n
        poids *= 2
    resultat = ""
    while poids >= 1:
        if n >= poids:
            resultat += "1"
            n -= poids
        else:
            resultat += "0"
        poids //= 2
    return resultat

def dec_vers_bin_while(n):
    if n == 0:
        return "0"
    resultat = ""
    while n > 0:
        resultat = str(n % 2) + resultat
        n = n // 2
    return resultat

